[CmdletBinding()] param([string]$ResourceName,[string]$ResourceType,[Parameter(Mandatory)][string]$ResourceGroup,[Parameter(Mandatory)][string]$OutputDirectory,[string]$Subscription)
. (Join-Path $PSScriptRoot 'Common-AzureCollector.ps1');$doc=New-CollectorDocument $ResourceType $ResourceName $ResourceGroup $Subscription
$app=Invoke-AzCommandJson 'monitor.app-insights.component.show' @('monitor','app-insights','component','show','--app',$ResourceName,'--resource-group',$ResourceGroup) $Subscription -Required;Add-CollectorSection $doc 'show' $app;if($app.data.id){Add-StandardResourceEvidence $doc $app.data.id $Subscription};$file=Join-Path $OutputDirectory ('app-insights-{0}.json' -f (ConvertTo-CollectorSafeFileName $ResourceName));Save-CollectorDocument $doc $file;[pscustomobject]@{resourceType='appInsights';name=$ResourceName;outputFile=$file}